    public var inUseForIO: Swift.Int32 = 0
    /// The number of threads which are currently calling user code (servant dispatch, AMI callbacks, etc).
    public var inUseForUser: Swift.Int32 = 0
    /// The number of threads which are currently performing other activities such as DNS lookups, garbage
    /// collection, etc. These are all the other threads created by the Ice runtime that are not counted in
    /// `inUseForUser` or `inUseForIO`.
    public var inUseForOther: Swift.Int32 = 0

    public required init() {
        super.init()
    }

    public init(id: Swift.String, total: Swift.Int64 = 0, current: Swift.Int32 = 0, totalLifetime: Swift.Int64 = 0, failures: Swift.Int32 = 0, inUseForIO: Swift.Int32 = 0, inUseForUser: Swift.Int32 = 0, inUseForOther: Swift.Int32 = 0) {
        self.inUseForIO = inUseForIO
        self.inUseForUser = inUseForUser
        self.inUseForOther = inUseForOther
        super.init(id: id, total: total, current: current, totalLifetime: totalLifetime, failures: failures)
    }

    /// - Returns: The Slice type ID of the interface supported by this object.
    open override class func ice_staticId() -> Swift.String { "::IceMX::ThreadMetrics" }

    open override func _iceReadImpl(from istr: InputStream) throws {
        _ = try istr.startSlice()
        self.inUseForIO = try istr.read()
        self.inUseForUser = try istr.read()
        self.inUseForOther = try istr.read()
        try istr.endSlice()
        try super._iceReadImpl(from: istr);
    }

    open override func _iceWriteImpl(to ostr: OutputStream) {
        ostr.startSlice(typeId: ThreadMetrics.ice_staticId(), compactId: -1, last: false)
        ostr.write(self.inUseForIO)
        ostr.write(self.inUseForUser)
        ostr.write(self.inUseForOther)
        ostr.endSlice()
        super._iceWriteImpl(to: ostr);
    }
}

