/// Provide measurements for proxy invocations. Proxy invocations can either be sent over the wire or be collocated.
open class InvocationMetrics: Metrics {
    /// The number of retries for the invocations.
    public var retry: Swift.Int32 = 0
    /// The number of invocations that failed with a user exception.
    public var userException: Swift.Int32 = 0
    /// The remote invocation metrics map.
    public var remotes: MetricsMap = MetricsMap()
    /// The collocated invocation metrics map.
    public var collocated: MetricsMap = MetricsMap()

    public required init() {
        super.init()
    }

    public init(id: Swift.String, total: Swift.Int64 = 0, current: Swift.Int32 = 0, totalLifetime: Swift.Int64 = 0, failures: Swift.Int32 = 0, retry: Swift.Int32 = 0, userException: Swift.Int32 = 0, remotes: MetricsMap, collocated: MetricsMap) {
        self.retry = retry
        self.userException = userException
        self.remotes = remotes
        self.collocated = collocated
        super.init(id: id, total: total, current: current, totalLifetime: totalLifetime, failures: failures)
    }

    /// - Returns: The Slice type ID of the interface supported by this object.
    open override class func ice_staticId() -> Swift.String { "::IceMX::InvocationMetrics" }

    open override func _iceReadImpl(from istr: InputStream) throws {
        _ = try istr.startSlice()
        self.retry = try istr.read()
        self.userException = try istr.read()
        self.remotes = try MetricsMapHelper.read(from: istr)
        self.collocated = try MetricsMapHelper.read(from: istr)
        try istr.endSlice()
        try super._iceReadImpl(from: istr);
    }

    open override func _iceWriteImpl(to ostr: OutputStream) {
        ostr.startSlice(typeId: InvocationMetrics.ice_staticId(), compactId: -1, last: false)
        ostr.write(self.retry)
        ostr.write(self.userException)
        MetricsMapHelper.write(to: ostr, value: self.remotes)
        MetricsMapHelper.write(to: ostr, value: self.collocated)
        ostr.endSlice()
        super._iceWriteImpl(to: ostr);
    }
}

