/// Dispatcher for `MetricsAdmin` servants.
public struct MetricsAdminDisp: Ice.Dispatcher {
    public let servant: MetricsAdmin
    private static let defaultObject = ObjectI<MetricsAdminTraits>()

    public init(_ servant: MetricsAdmin) {
        self.servant = servant
    }

    public func dispatch(_ request: Ice.IncomingRequest) async throws -> Ice.OutgoingResponse {
        switch request.current.operation {
        case "getMetricsViewNames":
            try await servant._iceD_getMetricsViewNames(request)
        case "enableMetricsView":
            try await servant._iceD_enableMetricsView(request)
        case "disableMetricsView":
            try await servant._iceD_disableMetricsView(request)
        case "getMetricsView":
            try await servant._iceD_getMetricsView(request)
        case "getMapMetricsFailures":
            try await servant._iceD_getMapMetricsFailures(request)
        case "getMetricsFailures":
            try await servant._iceD_getMetricsFailures(request)
        case "ice_id":
            try await (servant as? Ice.Object ?? MetricsAdminDisp.defaultObject)._iceD_ice_id(request)
        case "ice_ids":
            try await (servant as? Ice.Object ?? MetricsAdminDisp.defaultObject)._iceD_ice_ids(request)
        case "ice_isA":
            try await (servant as? Ice.Object ?? MetricsAdminDisp.defaultObject)._iceD_ice_isA(request)
        case "ice_ping":
            try await (servant as? Ice.Object ?? MetricsAdminDisp.defaultObject)._iceD_ice_ping(request)
        default:
            throw Ice.OperationNotExistException()
        }
    }
}

/// The metrics administrative facet interface. This interface allows remote administrative clients to access the
/// metrics of an application that enabled the Ice administrative facility and configured one or more metrics views.
public protocol MetricsAdmin {
    /// Gets the names of enabled and disabled metrics.
    ///
    /// - Parameter current: The Current object for the dispatch.
    ///
    /// - Returns:
    ///   - returnValue: The name of the enabled views.
    ///   - disabledViews: The names of the disabled views.
    func getMetricsViewNames(current: Current) async throws -> (returnValue: StringSeq, disabledViews: StringSeq)

    /// Enables a metrics view.
    ///
    /// - Parameters:
    ///   - name: The metrics view name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws:
    ///   - UnknownMetricsView Thrown when the metrics view cannot be found.
    func enableMetricsView(name: Swift.String, current: Current) async throws

    /// Disables a metrics view.
    ///
    /// - Parameters:
    ///   - name: The metrics view name.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Throws:
    ///   - UnknownMetricsView Thrown when the metrics view cannot be found.
    func disableMetricsView(name: Swift.String, current: Current) async throws

    /// Gets the metrics objects for the given metrics view.
    ///
    /// - Parameters:
    ///   - view: The name of the metrics view.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns:
    ///   - returnValue: The metrics view data, a dictionary of metric maps for each metrics class configured with the view.
    /// The timestamp allows the client to compute averages which are not dependent of the invocation latency for
    /// this operation.
    ///   - timestamp: The local time of the process when the metrics object were retrieved.
    ///
    /// - Throws:
    ///   - UnknownMetricsView Thrown when the metrics view cannot be found.
    func getMetricsView(view: Swift.String, current: Current) async throws -> (returnValue: MetricsView, timestamp: Swift.Int64)

    /// Gets the metrics failures associated with the given view and map.
    ///
    /// - Parameters:
    ///   - view: The name of the metrics view.
    ///   - map: The name of the metrics map.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The metrics failures associated with the map.
    ///
    /// - Throws:
    ///   - UnknownMetricsView Thrown when the metrics view cannot be found.
    func getMapMetricsFailures(view: Swift.String, map: Swift.String, current: Current) async throws -> MetricsFailuresSeq

    /// Gets the metrics failure associated for the given metrics.
    ///
    /// - Parameters:
    ///   - view: The name of the metrics view.
    ///   - map: The name of the metrics map.
    ///   - id: The ID of the metrics.
    ///   - current: The Current object for the dispatch.
    ///
    /// - Returns: The metrics failures associated with the metrics.
    ///
    /// - Throws:
    ///   - UnknownMetricsView Thrown when the metrics view cannot be found.
    func getMetricsFailures(view: Swift.String, map: Swift.String, id: Swift.String, current: Current) async throws -> MetricsFailures
}

/// The metrics administrative facet interface. This interface allows remote administrative clients to access the
/// metrics of an application that enabled the Ice administrative facility and configured one or more metrics views.
///
/// MetricsAdmin Methods:
///  - getMetricsViewNames: Gets the names of enabled and disabled metrics.
///  - enableMetricsView: Enables a metrics view.
///  - disableMetricsView: Disables a metrics view.
///  - getMetricsView: Gets the metrics objects for the given metrics view.
///  - getMapMetricsFailures: Gets the metrics failures associated with the given view and map.
///  - getMetricsFailures: Gets the metrics failure associated for the given metrics.
extension MetricsAdmin {
    public func _iceD_getMetricsViewNames(_ request: Ice.IncomingRequest) async throws -> Ice.OutgoingResponse {
        
        try request.current.checkNonIdempotent()
        _ = try request.inputStream.skipEmptyEncapsulation()
        let result = try await self.getMetricsViewNames(current: request.current)
        return request.current.makeOutgoingResponse(result, formatType: nil) { ostr, value in 
            let (iceP_returnValue, iceP_disabledViews) = value
            ostr.write(iceP_disabledViews)
            ostr.write(iceP_returnValue)
        }
    }

    public func _iceD_enableMetricsView(_ request: Ice.IncomingRequest) async throws -> Ice.OutgoingResponse {
        
        try request.current.checkNonIdempotent()
        let istr = request.inputStream
        _ = try istr.startEncapsulation()
        let iceP_name: Swift.String = try istr.read()
        try await self.enableMetricsView(name: iceP_name, current: request.current)
        return request.current.makeEmptyOutgoingResponse()
    }

    public func _iceD_disableMetricsView(_ request: Ice.IncomingRequest) async throws -> Ice.OutgoingResponse {
        
        try request.current.checkNonIdempotent()
        let istr = request.inputStream
        _ = try istr.startEncapsulation()
        let iceP_name: Swift.String = try istr.read()
        try await self.disableMetricsView(name: iceP_name, current: request.current)
        return request.current.makeEmptyOutgoingResponse()
    }

    public func _iceD_getMetricsView(_ request: Ice.IncomingRequest) async throws -> Ice.OutgoingResponse {
        
        try request.current.checkNonIdempotent()
        let istr = request.inputStream
        _ = try istr.startEncapsulation()
        let iceP_view: Swift.String = try istr.read()
        let result = try await self.getMetricsView(view: iceP_view, current: request.current)
        return request.current.makeOutgoingResponse(result, formatType: .slicedFormat) { ostr, value in 
            let (iceP_returnValue, iceP_timestamp) = value
            ostr.write(iceP_timestamp)
            MetricsViewHelper.write(to: ostr, value: iceP_returnValue)
            ostr.writePendingValues()
        }
    }

    public func _iceD_getMapMetricsFailures(_ request: Ice.IncomingRequest) async throws -> Ice.OutgoingResponse {
        
        try request.current.checkNonIdempotent()
        let istr = request.inputStream
        _ = try istr.startEncapsulation()
        let iceP_view: Swift.String = try istr.read()
        let iceP_map: Swift.String = try istr.read()
        let result = try await self.getMapMetricsFailures(view: iceP_view, map: iceP_map, current: request.current)
        return request.current.makeOutgoingResponse(result, formatType: nil) { ostr, value in 
            let iceP_returnValue = value
            MetricsFailuresSeqHelper.write(to: ostr, value: iceP_returnValue)
        }
    }

    public func _iceD_getMetricsFailures(_ request: Ice.IncomingRequest) async throws -> Ice.OutgoingResponse {
        
        try request.current.checkNonIdempotent()
        let istr = request.inputStream
        _ = try istr.startEncapsulation()
        let iceP_view: Swift.String = try istr.read()
        let iceP_map: Swift.String = try istr.read()
        let iceP_id: Swift.String = try istr.read()
        let result = try await self.getMetricsFailures(view: iceP_view, map: iceP_map, id: iceP_id, current: request.current)
        return request.current.makeOutgoingResponse(result, formatType: nil) { ostr, value in 
            let iceP_returnValue = value
            ostr.write(iceP_returnValue)
        }
    }
}
